export const hhsHti1HipaaControls: FrameworkControl[] = [
  {"controlId": "HTI1-170.315(b)(11)(i)", "framework": "HHS_HTI_1", "category": null, "title": "Decision support intervention interaction", "text": "Decision support intervention interaction. Interventions provided to a user must occur when a user is interacting with technology.", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": []},
  {"controlId": "HTI1-170.315(b)(11)(ii)(A)", "framework": "HHS_HTI_1", "category": null, "title": "Role-based configuration of interventions by a limited set of identified users", "text": "Enable interventions specified in paragraphs (b)(11)(iii) of this section to be configured by a limited set of identified users based on a user's role.", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "iso_access_control", "relation": "partial", "rationale": "Overlap: the ISO_27001 mapping iso_access_control (Access Control) evidences audit/tool_action events and the absence of LEASE_SCOPE_DENIED or LEASE_INVALID_OR_MISSING audits, which bears on part of this clause. Not evidenced: AMC evidences lease/scope denials for agent actions; it does not evidence which human roles may configure an intervention inside the EHR."}]},
  {"controlId": "HTI1-170.315(b)(11)(ii)(B)", "framework": "HHS_HTI_1", "category": null, "title": "Interventions on data incorporated from transition-of-care summaries", "text": "Enable interventions when a patient's medications, allergies and intolerance, and problems are incorporated from a transition of care or referral summary received and pursuant to paragraph (b)(2)(iii)(D) of this section.", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": []},
  {"controlId": "HTI1-170.315(b)(11)(ii)(C)", "framework": "HHS_HTI_1", "category": "§170.315(b)(11)(ii)(C) Intervention feedback", "title": "Intervention feedback capture and export", "text": "Enable a user to provide electronic feedback data for evidence-based decision support interventions selected via the capability provided in paragraph (b)(11)(iii)(A) of this section and make available such feedback data to a limited set of identified users for export, in a computable format, including at a minimum the intervention, action taken, user feedback provided (if applicable), user, date, and location.", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hti1_dsi_feedback", "relation": "partial", "rationale": "This family's mapping hti1_dsi_feedback (§170.315(b)(11)(ii)(C) Intervention feedback) addresses part of the clause with review/audit events. Not evidenced: The text scopes feedback to evidence-based DSIs selected under (iii)(A); hti1_dsi_feedback reads it as feedback on any intervention, so a predictive agent's feedback log would be over-credited."}]},
  {"controlId": "HTI1-170.315(b)(11)(iii)(A)", "framework": "HHS_HTI_1", "category": null, "title": "Selection (activation) of evidence-based DSIs by a limited set of identified users", "text": "Enable a limited set of identified users to select (i.e., activate) electronic decision support interventions (in addition to drug-drug and drug-allergy contraindication checking) that are: (A) Evidence-based decision support interventions and use any data based on the following data expressed in the standards in § 170.213:", "textKind": "verbatim-excerpt", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": []},
  {"controlId": "HTI1-170.315(b)(11)(iii)(B)", "framework": "HHS_HTI_1", "category": null, "title": "Selection (activation) of Predictive DSIs", "text": "(B) Predictive Decision Support Interventions and use any data expressed in the standards in § 170.213.", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "iso_access_control", "relation": "partial", "rationale": "Overlap: the ISO_27001 mapping iso_access_control (Access Control) evidences audit/tool_action events and the absence of LEASE_SCOPE_DENIED or LEASE_INVALID_OR_MISSING audits, which bears on part of this clause. Not evidenced: AMC can evidence that an agent acts only under a valid lease and that governance cannot be bypassed; it cannot evidence who in the deploying organisation activated the agent as a DSI."}, {"mappingId": "hti1_dsi_governance", "relation": "partial", "rationale": "This family's mapping hti1_dsi_governance (§170.315(b)(11)(vi)(C) Governance) addresses part of the clause with audit/review events and the governance_bypass pack. Not evidenced: AMC can evidence that an agent acts only under a valid lease and that governance cannot be bypassed; it cannot evidence who in the deploying organisation activated the agent as a DSI."}]},
  {"controlId": "HTI1-170.315(b)(11)(iv)(A)", "framework": "HHS_HTI_1", "category": "§170.315(b)(11)(iv) Source attributes", "title": "Source attributes for evidence-based DSIs", "text": "Source attributes listed in paragraphs (b)(11)(iv)(A) and (B) of this section must be supported. (A) For evidence-based decision support interventions: (1) Bibliographic citation of the intervention (clinical research or guideline); (2) Developer of the intervention (translation from clinical research or guideline); (3) Funding source of the technical implementation for the intervention(s) development; (4) Release and, if applicable, revision dates of the intervention or reference source; (5) Use of race as expressed in the standards in § 170.213; [..] (13) Use of health status assessments data as expressed in the standards in § 170.213.", "textKind": "verbatim-excerpt", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hti1_dsi_source_attributes", "relation": "partial", "rationale": "This family's mapping hti1_dsi_source_attributes (§170.315(b)(11)(iv) Source attributes) addresses part of the clause with artifact/audit events and the truthfulness pack. Not evidenced: hti1_dsi_source_attributes describes the predictive attributes (iv)(B)(1)-(9) only; nothing evidences the 13 evidence-based attributes (citation, developer, funding, release dates, use of race/ethnicity/language/sexual orientation/gender identity/sex/DOB/SDOH/health status)."}]},
  {"controlId": "HTI1-170.315(b)(11)(iv)(B)(1)-(2)", "framework": "HHS_HTI_1", "category": "§170.315(b)(11)(iv) Source attributes", "title": "Predictive DSI source attributes: details, output and intended use", "text": "(1) Details and output of the intervention, including: (i) Name and contact information for the intervention developer; (ii) Funding source of the technical implementation for the intervention(s) development; (iii) Description of value that the intervention produces as an output; and (iv) Whether the intervention output is a prediction, classification, recommendation, evaluation, analysis, or other type of output. (2) Purpose of the intervention, including: (i) Intended use of the intervention; (ii) Intended patient population(s) for the intervention's use; (iii) Intended user(s); and (iv) Intended decision-making role for which the intervention was designed to be used/for (e.g., informs, augments, replaces clinical management).", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hti1_dsi_source_attributes", "relation": "partial", "rationale": "This family's mapping hti1_dsi_source_attributes (§170.315(b)(11)(iv) Source attributes) addresses part of the clause with artifact/audit events and the truthfulness pack. Not evidenced: AMC checks that artifact/audit events exist and that the truthfulness pack passes; it does not parse an artifact for the eight named fields, so a model card missing 'intended decision-making role' still satisfies the evidence rule."}, {"mappingId": "euai_art11_technical_documentation", "relation": "partial", "rationale": "Overlap: the EU_AI_ACT mapping euai_art11_technical_documentation (Art. 11 Technical Documentation) evidences artifact/review/audit events, which bears on part of this clause. Not evidenced: AMC checks that artifact/audit events exist and that the truthfulness pack passes; it does not parse an artifact for the eight named fields, so a model card missing 'intended decision-making role' still satisfies the evidence rule."}]},
  {"controlId": "HTI1-170.315(b)(11)(iv)(B)(3)", "framework": "HHS_HTI_1", "category": "§170.315(b)(11)(iv) Source attributes", "title": "Predictive DSI source attributes: cautioned out-of-scope use", "text": "(3) Cautioned out-of-scope use of the intervention, including: (i) Description of tasks, situations, or populations where a user is cautioned against applying the intervention; and (ii) Known risks, inappropriate settings, inappropriate uses, or known limitations.", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hti1_dsi_source_attributes", "relation": "partial", "rationale": "This family's mapping hti1_dsi_source_attributes (§170.315(b)(11)(iv) Source attributes) addresses part of the clause with artifact/audit events and the truthfulness pack. Not evidenced: No AMC check that the agent refuses or flags requests in the cautioned out-of-scope populations or tasks it documents."}, {"mappingId": "euai_art13_transparency", "relation": "partial", "rationale": "Overlap: the EU_AI_ACT mapping euai_art13_transparency (Art. 13 Transparency) evidences artifact/review events, which bears on part of this clause. Not evidenced: No AMC check that the agent refuses or flags requests in the cautioned out-of-scope populations or tasks it documents."}]},
  {"controlId": "HTI1-170.315(b)(11)(iv)(B)(4)-(6)", "framework": "HHS_HTI_1", "category": "§170.315(b)(11)(iv) Source attributes", "title": "Predictive DSI source attributes: development data, fairness process, external validation", "text": "(4) Intervention development details and input features, including at a minimum: (i) Exclusion and inclusion criteria that influenced the training data set; [..] (iv) Description of relevance of training data to intended deployed setting; and (5) Process used to ensure fairness in development of the intervention, including: (i) Description of the approach the intervention developer has taken to ensure that the intervention's output is fair; and (ii) Description of approaches to manage, reduce, or eliminate bias. (6) External validation process, including: (i) Description of the data source, clinical setting, or environment where an intervention's validity and fairness has been assessed, other than the source of training and testing data", "textKind": "verbatim-excerpt", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hti1_dsi_source_attributes", "relation": "partial", "rationale": "This family's mapping hti1_dsi_source_attributes (§170.315(b)(11)(iv) Source attributes) addresses part of the clause with artifact/audit events and the truthfulness pack. Not evidenced: AMC has no evidence type for training-data inclusion/exclusion criteria, demographic representativeness, or an external validation by a named party. For an LLM-based agent these attributes usually depend on the model provider and are 'not available' under (v)(A)(2)."}, {"mappingId": "euai_art10_data_governance", "relation": "partial", "rationale": "Overlap: the EU_AI_ACT mapping euai_art10_data_governance (Art. 10 Data Governance) evidences audit/artifact/review events and the absence of SECRET_EXFILTRATION_SUCCEEDED or POLICY_VIOLATION audits, which bears on part of this clause. Not evidenced: AMC has no evidence type for training-data inclusion/exclusion criteria, demographic representativeness, or an external validation by a named party. For an LLM-based agent these attributes usually depend on the model provider and are 'not available' under (v)(A)(2)."}]},
  {"controlId": "HTI1-170.315(b)(11)(iv)(B)(7)", "framework": "HHS_HTI_1", "category": "§170.315(b)(11)(iv) Source attributes", "title": "Predictive DSI source attributes: quantitative validity and fairness measures", "text": "(7) Quantitative measures of performance, including: (i) Validity of intervention in test data derived from the same source as the initial training data; (ii) Fairness of intervention in test data derived from the same source as the initial training data; (iii) Validity of intervention in data external to or from a different source than the initial training data; (iv) Fairness of intervention in data external to or from a different source than the initial training data;", "textKind": "verbatim-excerpt", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hti1_dsi_source_attributes", "relation": "partial", "rationale": "This family's mapping hti1_dsi_source_attributes (§170.315(b)(11)(iv) Source attributes) addresses part of the clause with artifact/audit events and the truthfulness pack. Not evidenced: AMC metric/test events are generic; no mapping requires a fairness metric broken out by the (iv)(A)(5)-(13) demographic variables, and none distinguishes same-source from external test data."}, {"mappingId": "nist_measure", "relation": "partial", "rationale": "Overlap: the NIST_AI_RMF mapping nist_measure (Measure) evidences metric/test/audit events and the absence of TRACE_RECEIPT_INVALID or TRACE_EVENT_HASH_NOT_FOUND audits, which bears on part of this clause. Not evidenced: AMC metric/test events are generic; no mapping requires a fairness metric broken out by the (iv)(A)(5)-(13) demographic variables, and none distinguishes same-source from external test data."}]},
  {"controlId": "HTI1-170.315(b)(11)(iv)(B)(8)-(9)", "framework": "HHS_HTI_1", "category": "§170.315(b)(11)(iv) Source attributes", "title": "Predictive DSI source attributes: ongoing monitoring in local data and update schedule", "text": "(8) Ongoing maintenance of intervention implementation and use, including: (i) Description of process and frequency by which the intervention's validity is monitored over time; (ii) Validity of intervention in local data; (iii) Description of the process and frequency by which the intervention's fairness is monitored over time; (iv) Fairness of intervention in local data; and (9) Update and continued validation or fairness assessment schedule, including: (i) Description of process and frequency by which the intervention is updated; and (ii) Description of frequency by which the intervention's performance is corrected when risks related to validity and fairness are identified.", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hti1_dsi_source_attributes", "relation": "partial", "rationale": "This family's mapping hti1_dsi_source_attributes (§170.315(b)(11)(iv) Source attributes) addresses part of the clause with artifact/audit events and the truthfulness pack. Not evidenced: DRIFT_REGRESSION_DETECTED audits show validity drift was not flagged; AMC has no 'fairness in local data' measurement and no check that monitoring happens at the documented frequency."}, {"mappingId": "hti1_dsi_risk_mitigation", "relation": "partial", "rationale": "This family's mapping hti1_dsi_risk_mitigation (§170.315(b)(11)(vi)(B) Risk mitigation) addresses part of the clause with test/review events and the absence of DRIFT_REGRESSION_DETECTED audits. Not evidenced: DRIFT_REGRESSION_DETECTED audits show validity drift was not flagged; AMC has no 'fairness in local data' measurement and no check that monitoring happens at the documented frequency."}, {"mappingId": "euai_art72_post_market_monitoring", "relation": "partial", "rationale": "Overlap: the EU_AI_ACT mapping euai_art72_post_market_monitoring (Art. 72 Post-Market Monitoring) evidences metric/audit/test events and the absence of DRIFT_REGRESSION_DETECTED audits, which bears on part of this clause. Not evidenced: DRIFT_REGRESSION_DETECTED audits show validity drift was not flagged; AMC has no 'fairness in local data' measurement and no check that monitoring happens at the documented frequency."}]},
  {"controlId": "HTI1-170.315(b)(11)(v)(A)", "framework": "HHS_HTI_1", "category": "§170.315(b)(11)(v) Source attribute access and modification", "title": "Access to plain-language source attributes; flag unavailable attributes", "text": "(1) For evidence-based decision support interventions and Predictive Decision Support Interventions supplied by the health IT developer as part of its Health IT Module, the Health IT Module must enable a limited set of identified users to access complete and up-to-date plain language descriptions of source attribute information specified in paragraphs (b)(11)(iv)(A) and (B) of this section. (2) For Predictive Decision Support Interventions supplied by the health IT developer as part of its Health IT Module, the Health IT Module must indicate when information is not available for review for source attributes in paragraphs", "textKind": "verbatim-excerpt", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hti1_dsi_source_attribute_access", "relation": "partial", "rationale": "This family's mapping hti1_dsi_source_attribute_access (§170.315(b)(11)(v) Source attribute access and modification) addresses part of the clause with artifact/review events and the absence of TRACE_RECEIPT_INVALID or TRACE_EVENT_HASH_NOT_FOUND audits. Not evidenced: No AMC check that each unavailable attribute is explicitly flagged as unavailable rather than omitted."}]},
  {"controlId": "HTI1-170.315(b)(11)(v)(B)", "framework": "HHS_HTI_1", "category": "§170.315(b)(11)(v) Source attribute access and modification", "title": "Record, change and access source attributes (incl. additional attributes)", "text": "(1) For evidence-based decision support interventions and Predictive Decision Support Interventions, the Health IT Module must enable a limited set of identified users to record, change, and access source attributes in paragraphs (b)(11)(iv)(A) and (B) of this section. (2) For Predictive Decision Support Interventions, the Health IT Module must enable a limited set of identified users to record, change, and access additional source attributes not specified in paragraph (b)(11)(iv)(B) of this section.", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hti1_dsi_source_attribute_access", "relation": "partial", "rationale": "This family's mapping hti1_dsi_source_attribute_access (§170.315(b)(11)(v) Source attribute access and modification) addresses part of the clause with artifact/review events and the absence of TRACE_RECEIPT_INVALID or TRACE_EVENT_HASH_NOT_FOUND audits. Not evidenced: AMC does not evidence that only a limited set of identified users can edit the attributes."}]},
  {"controlId": "HTI1-170.315(b)(11)(vi)(A)", "framework": "HHS_HTI_1", "category": "§170.315(b)(11)(vi)(A) Risk analysis", "title": "Intervention risk management: risk analysis across eight characteristics", "text": "Intervention risk management practices must be applied for each Predictive Decision Support Intervention supplied by the health IT developer as part of its Health IT Module. (A) Risk analysis. The Predictive Decision Support Intervention(s) must be subject to analysis of potential risks and adverse impacts associated with the following characteristics: validity, reliability, robustness, fairness, intelligibility, safety, security, and privacy.", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hti1_dsi_risk_analysis", "relation": "partial", "rationale": "This family's mapping hti1_dsi_risk_analysis (§170.315(b)(11)(vi)(A) Risk analysis) addresses part of the clause with test/metric events, the hallucination pack and the injection pack. Not evidenced: hti1_dsi_risk_analysis evidences validity/robustness/security through hallucination and injection packs; fairness, intelligibility and privacy are not covered by any pack it requires."}, {"mappingId": "euai_art9_risk_management", "relation": "partial", "rationale": "Overlap: the EU_AI_ACT mapping euai_art9_risk_management (Art. 9 Risk Management) evidences audit/metric/review events, the duality pack and the absence of DRIFT_REGRESSION_DETECTED or BUDGET_EXCEEDED audits, which bears on part of this clause. Not evidenced: hti1_dsi_risk_analysis evidences validity/robustness/security through hallucination and injection packs; fairness, intelligibility and privacy are not covered by any pack it requires."}]},
  {"controlId": "HTI1-170.315(b)(11)(vi)(B)", "framework": "HHS_HTI_1", "category": "§170.315(b)(11)(vi)(B) Risk mitigation", "title": "Intervention risk management: risk mitigation", "text": "The Predictive Decision Support Intervention (s) must be subject to practices to mitigate risks, identified in accordance with paragraph (b)(11)(vi)(A) of this section;", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hti1_dsi_risk_mitigation", "relation": "partial", "rationale": "This family's mapping hti1_dsi_risk_mitigation (§170.315(b)(11)(vi)(B) Risk mitigation) addresses part of the clause with test/review events and the absence of DRIFT_REGRESSION_DETECTED audits. Not evidenced: AMC does not link a mitigation to the specific risk identified under (vi)(A); traceability from risk to mitigation is missing."}, {"mappingId": "nist_manage", "relation": "partial", "rationale": "Overlap: the NIST_AI_RMF mapping nist_manage (Manage) evidences audit/tool_action events and the absence of EXECUTE_FROZEN_ACTIVE or BUDGET_EXCEEDED audits, which bears on part of this clause. Not evidenced: AMC does not link a mitigation to the specific risk identified under (vi)(A); traceability from risk to mitigation is missing."}]},
  {"controlId": "HTI1-170.315(b)(11)(vi)(C)", "framework": "HHS_HTI_1", "category": "§170.315(b)(11)(vi)(C) Governance", "title": "Intervention risk management: governance of data acquisition, management and use", "text": "The Predictive Decision Support Intervention(s) must be subject to policies and implemented controls for governance, including how data are acquired, managed, and used.", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.315", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hti1_dsi_governance", "relation": "partial", "rationale": "This family's mapping hti1_dsi_governance (§170.315(b)(11)(vi)(C) Governance) addresses part of the clause with audit/review events and the governance_bypass pack. Not evidenced: governance_bypass shows policy cannot be bypassed at runtime; AMC does not evidence a written data-acquisition policy for training or retrieval data."}, {"mappingId": "iso42001_clause_8_operation", "relation": "partial", "rationale": "Overlap: the ISO_42001 mapping iso42001_clause_8_operation (Clause 8 Operation) evidences tool_action/tool_result/audit events and the absence of EXECUTE_WITHOUT_TICKET_ATTEMPTED or DIRECT_PROVIDER_BYPASS_SUSPECTED audits, which bears on part of this clause. Not evidenced: governance_bypass shows policy cannot be bypassed at runtime; AMC does not evidence a written data-acquisition policy for training or retrieval data."}]},
  {"controlId": "ONC-170.402(b)(4)", "framework": "HHS_HTI_1", "category": null, "title": "Ongoing review and update of source attributes, IRM practices and IRM summary from 2025-01-01", "text": "(4) For developers of Health IT Modules certified to § 170.315(b)(11), starting January 1, 2025, and on an ongoing basis thereafter, review and update as necessary source attribute information in § 170.315(b)(11)(iv)(A) and (B), intervention risk management practices described in § 170.315(b)(11)(vi), and summary information provided through § 170.523(f)(1)(xxi).", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.402", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hti1_dsi_source_attributes", "relation": "partial", "rationale": "This family's mapping hti1_dsi_source_attributes (§170.315(b)(11)(iv) Source attributes) addresses part of the clause with artifact/audit events and the truthfulness pack. Not evidenced: No AMC check of review cadence; an artifact produced once and never revised still satisfies the source-attribute evidence rule."}, {"mappingId": "hti1_dsi_risk_mitigation", "relation": "partial", "rationale": "This family's mapping hti1_dsi_risk_mitigation (§170.315(b)(11)(vi)(B) Risk mitigation) addresses part of the clause with test/review events and the absence of DRIFT_REGRESSION_DETECTED audits. Not evidenced: No AMC check of review cadence; an artifact produced once and never revised still satisfies the source-attribute evidence rule."}]},
  {"controlId": "ONC-170.523(f)(1)(xxi)", "framework": "HHS_HTI_1", "category": null, "title": "Public hyperlink to IRM summary information", "text": "Where applicable, summary information of the intervention risk management practices listed in § 170.315(b)(11)(vi) is submitted by the health IT developer via publicly accessible hyperlink that allows any person to access the summary information directly without any preconditions or additional steps.", "textKind": "verbatim", "status": "law", "sourceUrl": "https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-45.xml?part=170&section=170.523", "retrievedAt": "2026-10-04", "verified": true, "mappings": []},
  {"controlId": "NPRM-164.308(a)(1)", "framework": "HIPAA", "category": null, "title": "Technology asset inventory and network map", "text": "(1) Standard: Technology asset inventory —(i) General. Conduct and maintain an accurate and thorough written inventory and a network map of the covered entity's or business associate's electronic information systems and all technology assets that may affect the confidentiality, integrity, or availability of electronic protected health information. [..] (A) Inventory. Develop a written inventory of the covered entity's or business associate's technology assets that contains the identification, version, person accountable, and location of each technology asset. [..] On an ongoing basis, but at least once every 12 months.", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": []},
  {"controlId": "NPRM-164.308(a)(2)", "framework": "HIPAA", "category": "§164.308 Administrative Safeguards", "title": "Written risk analysis, reviewed at least every 12 months", "text": "(2) Standard: Risk analysis —(i) General. Conduct an accurate and comprehensive written assessment of the potential risks and vulnerabilities to the confidentiality, integrity, and availability of all electronic protected health information created, received, maintained, or transmitted by the covered entity or business associate. [..] (B) Maintenance. Review, verify, and update the written assessment on an ongoing basis, but at least once every 12 months", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_administrative_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_administrative_safeguards (§164.308 Administrative Safeguards) addresses part of the clause with audit/llm_request/tool_action events, the governance_bypass pack and the absence of GOVERNANCE_BYPASS_SUCCEEDED or EXECUTE_WITHOUT_TICKET_ATTEMPTED audits. Not evidenced: AMC evidences agent behaviour, not the entity's written risk assessment; nothing checks the 12-month review or the eight required assessment elements."}, {"mappingId": "iso_risk_management", "relation": "partial", "rationale": "Overlap: the ISO_27001 mapping iso_risk_management (Risk Management) evidences audit/metric events and the duality pack, which bears on part of this clause. Not evidenced: AMC evidences agent behaviour, not the entity's written risk assessment; nothing checks the 12-month review or the eight required assessment elements."}]},
  {"controlId": "NPRM-164.308(a)(3)", "framework": "HIPAA", "category": "§164.308 Administrative Safeguards", "title": "Written evaluation before environmental or operational change", "text": "(3) Standard: Evaluation —(i) General. Perform a written technical and nontechnical evaluation to determine whether a change in the covered entity's or business associate's environment or operations may affect the confidentiality, integrity, or availability of electronic protected health information. (ii) Implementation specifications —(A) Performance. Perform a written technical and nontechnical evaluation within a reasonable period of time before making a change in the covered entity's or business associate's environment or operations", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_administrative_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_administrative_safeguards (§164.308 Administrative Safeguards) addresses part of the clause with audit/llm_request/tool_action events, the governance_bypass pack and the absence of GOVERNANCE_BYPASS_SUCCEEDED or EXECUTE_WITHOUT_TICKET_ATTEMPTED audits. Not evidenced: A model, prompt or tool change to an agent is such a change; AMC does not require a pre-change evaluation record tied to the change."}, {"mappingId": "euai_art17_quality_management", "relation": "partial", "rationale": "Overlap: the EU_AI_ACT mapping euai_art17_quality_management (Art. 17 Quality Management) evidences audit/test/metric events and the absence of CONFIG_SIGNATURE_INVALID or EXECUTE_FROZEN_ACTIVE audits, which bears on part of this clause. Not evidenced: A model, prompt or tool change to an agent is such a change; AMC does not require a pre-change evaluation record tied to the change."}]},
  {"controlId": "NPRM-164.308(a)(4)", "framework": "HIPAA", "category": null, "title": "Patch management with 15/30-day clocks", "text": "(4) Standard: Patch management —(i) General. Implement written policies and procedures for applying patches and updating the configuration(s) of the covered entity's or business associate's relevant electronic information systems. [..] (1) Within 15 calendar days of identifying the need to patch, update, or upgrade the configuration of a relevant electronic information system to address a critical risk [..] (2) Within 30 calendar days of identifying the need to patch, update, or upgrade the configuration of a relevant electronic information system to address a high risk", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "fedramp_system_integrity", "relation": "partial", "rationale": "Overlap: the FEDRAMP mapping fedramp_system_integrity (SI System and Information Integrity) evidences test/audit events and the sbom-supply-chain pack, which bears on part of this clause. Not evidenced: No AMC measure of time-to-patch for agent dependencies, model versions or MCP servers."}]},
  {"controlId": "NPRM-164.308(a)(5)", "framework": "HIPAA", "category": null, "title": "Written risk management plan", "text": "(5) Standard: Risk management —(i) General. Implement security measures sufficient to reduce risks and vulnerabilities to all electronic protected health information to a reasonable and appropriate level. (ii) Implementation specifications —(A) Planning. Establish and implement a written risk management plan for reducing risks to all electronic protected health information", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "nist_manage", "relation": "partial", "rationale": "Overlap: the NIST_AI_RMF mapping nist_manage (Manage) evidences audit/tool_action events and the absence of EXECUTE_FROZEN_ACTIVE or BUDGET_EXCEEDED audits, which bears on part of this clause. Not evidenced: No HIPAA mapping names risk management; no evidence of a written, prioritised plan."}, {"mappingId": "iso_risk_management", "relation": "partial", "rationale": "Overlap: the ISO_27001 mapping iso_risk_management (Risk Management) evidences audit/metric events and the duality pack, which bears on part of this clause. Not evidenced: No HIPAA mapping names risk management; no evidence of a written, prioritised plan."}]},
  {"controlId": "NPRM-164.308(a)(6)", "framework": "HIPAA", "category": null, "title": "Sanction policy for workforce members", "text": "(6) Standard: Sanction policy —(i) General. Apply appropriate sanctions against workforce members who fail to comply with the security policies and procedures of the covered entity or business associate.", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": []},
  {"controlId": "NPRM-164.308(a)(7)", "framework": "HIPAA", "category": null, "title": "Information system activity review, by persons and technology assets", "text": "(7) Standard: Information system activity review —(i) General. Implement written policies and procedures for regularly reviewing records of activity in the covered entity's or business associate's relevant electronic information systems. (ii) Implementation specifications —(A) Policies and procedures. Establish written policies and procedures for retaining and reviewing records of activity in the covered entity's or business associate's relevant electronic information systems by persons and technology assets, including the frequency for reviewing such records.", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "iso_logging_monitoring", "relation": "partial", "rationale": "Overlap: the ISO_27001 mapping iso_logging_monitoring (Logging & Monitoring) evidences audit/metric/llm_request/llm_response events, which bears on part of this clause. Not evidenced: AMC records agent activity (llm_request/response, tool_action); it does not evidence that a human reviewed those records at a documented frequency."}, {"mappingId": "hipaa_technical_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_technical_safeguards (§164.312 Technical Safeguards) addresses part of the clause with audit/tool_action events, the exfiltration pack and the pii-detection-leakage pack. Not evidenced: AMC records agent activity (llm_request/response, tool_action); it does not evidence that a human reviewed those records at a documented frequency."}]},
  {"controlId": "NPRM-164.308(a)(8)", "framework": "HIPAA", "category": null, "title": "Assigned security official, in writing", "text": "(8) Standard: Assigned security responsibility. In writing, identify the security official who is responsible for the development and implementation of the policies and procedures, written or otherwise, and deployment of technical controls required by this subpart for the covered entity or business associate.", "textKind": "verbatim", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": []},
  {"controlId": "NPRM-164.308(a)(9)", "framework": "HIPAA", "category": "§164.308 Administrative Safeguards", "title": "Workforce security incl. 24-hour notice of access change", "text": "(9) Standard: Workforce security —(i) General. Implement written policies and procedures to ensure that all members of its workforce have appropriate access to electronic protected health information and relevant electronic information systems [..] (2) Notification must occur as soon as possible but no later than 24 hours after a change in or termination of a workforce member's authorization to access electronic protected health", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_administrative_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_administrative_safeguards (§164.308 Administrative Safeguards) addresses part of the clause with audit/llm_request/tool_action events, the governance_bypass pack and the absence of GOVERNANCE_BYPASS_SUCCEEDED or EXECUTE_WITHOUT_TICKET_ATTEMPTED audits. Not evidenced: AMC cannot evidence the 24-hour notification to other regulated entities, or that an agent's credentials were revoked when the human it acts for lost access."}]},
  {"controlId": "NPRM-164.308(a)(10)", "framework": "HIPAA", "category": "§164.308 Administrative Safeguards", "title": "Information access management incl. network segmentation", "text": "(10) Standard: Information access management —(i) General. Establish and implement written policies and procedures for authorizing access to electronic protected health information and relevant electronic information systems that are consistent with the applicable requirements of subpart E of this part. [..] Network segmentation. Establish and implement written policies and procedures that ensure that a covered entity's or business associate's relevant electronic information systems are segmented to limit access to electronic protected health information to authorized workstations.", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_administrative_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_administrative_safeguards (§164.308 Administrative Safeguards) addresses part of the clause with audit/llm_request/tool_action events, the governance_bypass pack and the absence of GOVERNANCE_BYPASS_SUCCEEDED or EXECUTE_WITHOUT_TICKET_ATTEMPTED audits. Not evidenced: Lease scope denials show the agent stayed in its granted scope; AMC does not evidence network segmentation."}, {"mappingId": "iso_access_control", "relation": "partial", "rationale": "Overlap: the ISO_27001 mapping iso_access_control (Access Control) evidences audit/tool_action events and the absence of LEASE_SCOPE_DENIED or LEASE_INVALID_OR_MISSING audits, which bears on part of this clause. Not evidenced: Lease scope denials show the agent stayed in its granted scope; AMC does not evidence network segmentation."}]},
  {"controlId": "NPRM-164.308(a)(11)", "framework": "HIPAA", "category": "§164.308 Administrative Safeguards", "title": "Security awareness training", "text": "(11) Standard: Security awareness training —(i) General. Implement security awareness training for all workforce members on protection of electronic protected health information and information systems as necessary and appropriate for the members of the workforce to carry out their assigned function(s).", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_administrative_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_administrative_safeguards (§164.308 Administrative Safeguards) addresses part of the clause with audit/llm_request/tool_action events, the governance_bypass pack and the absence of GOVERNANCE_BYPASS_SUCCEEDED or EXECUTE_WITHOUT_TICKET_ATTEMPTED audits. Not evidenced: Human training records; the mapping names training but requires only agent-side events."}]},
  {"controlId": "NPRM-164.308(a)(12)", "framework": "HIPAA", "category": "§164.308 Administrative Safeguards", "title": "Security incident response plan, tested every 12 months", "text": "(12) Standard: Security incident procedures —(i) General. Implement written policies and procedures to respond to security incidents. (ii) Implementation specifications —(A) Planning and testing. (1) Establish written security incident response plan(s) and procedures documenting how workforce members are to report suspected or known security incidents [..] (3) Review and test security incident response plan(s) and procedures required by paragraph (a)(12)(ii)(A)(1) of this section at least once every 12 months", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_administrative_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_administrative_safeguards (§164.308 Administrative Safeguards) addresses part of the clause with audit/llm_request/tool_action events, the governance_bypass pack and the absence of GOVERNANCE_BYPASS_SUCCEEDED or EXECUTE_WITHOUT_TICKET_ATTEMPTED audits. Not evidenced: No evidence of a tested incident response plan covering agent-caused incidents (prompt injection, tool misuse, ePHI echo)."}, {"mappingId": "fedramp_incident_response", "relation": "partial", "rationale": "Overlap: the FEDRAMP mapping fedramp_incident_response (IR Incident Response) evidences audit/metric events and the absence of GOVERNANCE_BYPASS_SUCCEEDED or EXECUTE_WITHOUT_TICKET_ATTEMPTED audits, which bears on part of this clause. Not evidenced: No evidence of a tested incident response plan covering agent-caused incidents (prompt injection, tool misuse, ePHI echo)."}]},
  {"controlId": "NPRM-164.308(a)(13)", "framework": "HIPAA", "category": "§164.308 Administrative Safeguards", "title": "Contingency plan: criticality analysis and 72-hour restore", "text": "(13) Standard: Contingency plan —(i) General. Establish and implement as needed a written contingency plan, consisting of written policies and procedures for responding to an emergency or other occurrence—including but not limited to fire, vandalism, system failure, natural disaster, or security incident—that adversely affects relevant electronic information systems. (ii) Implementation specifications —(A) Criticality analysis. Perform and document an assessment of the relative criticality of the covered entity's or business associate's relevant electronic information systems and technology assets in its relevant electronic information systems. [..] (1) Establish (and implement as needed) written procedures to restore loss of the covered entity's or business associate's critical relevant electronic information systems and data within 72 hours of the loss.", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_administrative_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_administrative_safeguards (§164.308 Administrative Safeguards) addresses part of the clause with audit/llm_request/tool_action events, the governance_bypass pack and the absence of GOVERNANCE_BYPASS_SUCCEEDED or EXECUTE_WITHOUT_TICKET_ATTEMPTED audits. Not evidenced: circuit-breaker-reliability evidences graceful degradation of the agent; nothing evidences a 72-hour restore test."}, {"mappingId": "fedramp_contingency_planning", "relation": "partial", "rationale": "Overlap: the FEDRAMP mapping fedramp_contingency_planning (CP Contingency Planning) evidences metric/audit events and the circuit-breaker-reliability pack, which bears on part of this clause. Not evidenced: circuit-breaker-reliability evidences graceful degradation of the agent; nothing evidences a 72-hour restore test."}]},
  {"controlId": "NPRM-164.308(a)(14)", "framework": "HIPAA", "category": null, "title": "Annual compliance audit", "text": "(14) Standard: Compliance audit. Perform and document an audit at least once every 12 months of the covered entity's or business associate's compliance with each standard and implementation specification in this subpart.", "textKind": "verbatim", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": []},
  {"controlId": "NPRM-164.308(b)", "framework": "HIPAA", "category": "§164.314 Organizational Requirements", "title": "Business associate assurances plus written verification of technical safeguards every 12 months", "text": "(i)(A) A covered entity may permit a business associate to create, receive, maintain, or transmit electronic protected health information on the covered entity's behalf only if the covered entity obtains satisfactory assurances, in accordance with § 164.314(a), that the business associate will comply with this subpart and verifies that the business associate has deployed technical safeguards in accordance with the requirements of § 164.312. [..] (ii) Written verification. Obtain written verification from the business associate at least once every 12 months that the business associate has deployed the technical safeguards as required by § 164.312", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_organizational_requirements", "relation": "partial", "rationale": "This family's mapping hipaa_organizational_requirements (§164.314 Organizational Requirements) addresses part of the clause with audit events and the delegationTrustChain pack. Not evidenced: A model API or agent vendor that receives ePHI is a business associate; AMC evidences provider routing, not a BAA or the annual written verification."}, {"mappingId": "iso_supplier_security", "relation": "partial", "rationale": "Overlap: the ISO_27001 mapping iso_supplier_security (Supplier Security) evidences llm_request/llm_response/audit events and the absence of UNSAFE_PROVIDER_ROUTE or MODEL_ROUTE_MISMATCH audits, which bears on part of this clause. Not evidenced: A model API or agent vendor that receives ePHI is a business associate; AMC evidences provider routing, not a BAA or the annual written verification."}]},
  {"controlId": "NPRM-164.310", "framework": "HIPAA", "category": "§164.310 Physical Safeguards", "title": "Facility access controls and workstation security", "text": "(a) Standard: Facility access controls —(1) General. Establish and implement written policies and procedures to limit physical access to all of its relevant electronic information systems and the facility or facilities in which they are housed, while ensuring that properly authorized access is allowed. [..] Implement and modify physical safeguards for all workstations that access electronic protected health information or relevant electronic information systems, to address the written policies and procedures for workstation use required by paragraph (b) of this section and restrict access to authorized users.", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_physical_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_physical_safeguards (§164.310 Physical Safeguards) addresses part of the clause with audit events. Not evidenced: Physical facility controls are outside agent evidence; AMC runtimes emit no facility-access audit type."}]},
  {"controlId": "NPRM-164.312(a)", "framework": "HIPAA", "category": "§164.312 Technical Safeguards", "title": "Access control: unique identifier for each user and technology asset; separate privileged identities", "text": "(1) General. Deploy technical controls in relevant electronic information systems to allow access only to users and technology assets that have been granted access rights. (2) Implementation specifications —(i) Unique identification. Assign a unique name, number, and/or other identifier for tracking each user and technology asset in the covered entity or business associate's relevant electronic information systems. (ii) Administrative and increased access privileges. Separate user identities from identities used for administrative and other increased access privileges.", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_technical_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_technical_safeguards (§164.312 Technical Safeguards) addresses part of the clause with audit/tool_action events, the exfiltration pack and the pii-detection-leakage pack. Not evidenced: AMC does not check that each agent has its own identifier distinct from the human it acts for, or that elevated agent actions use a separate identity."}, {"mappingId": "iso_access_control", "relation": "partial", "rationale": "Overlap: the ISO_27001 mapping iso_access_control (Access Control) evidences audit/tool_action events and the absence of LEASE_SCOPE_DENIED or LEASE_INVALID_OR_MISSING audits, which bears on part of this clause. Not evidenced: AMC does not check that each agent has its own identifier distinct from the human it acts for, or that elevated agent actions use a separate identity."}, {"mappingId": "fedramp_identification_authentication", "relation": "partial", "rationale": "Overlap: the FEDRAMP mapping fedramp_identification_authentication (IA Identification and Authentication) evidences audit events and the agentIdentitySpoofing pack, which bears on part of this clause. Not evidenced: AMC does not check that each agent has its own identifier distinct from the human it acts for, or that elevated agent actions use a separate identity."}]},
  {"controlId": "NPRM-164.312(b)", "framework": "HIPAA", "category": null, "title": "Encrypt all ePHI at rest and in transit", "text": "(1) General. Deploy technical controls to encrypt and decrypt electronic protected health information using encryption that meets prevailing cryptographic standards. (2) Implementation specification. Encrypt all electronic protected health information at rest and in transit, except to the extent that an exception at paragraph (b)(3) of this section applies.", "textKind": "verbatim", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": []},
  {"controlId": "NPRM-164.312(c)", "framework": "HIPAA", "category": null, "title": "Configuration management to secure baselines", "text": "(1) General. Establish and deploy technical controls for securing the covered entity's or business associate's relevant electronic information systems and technology assets in its relevant electronic information systems, including workstations, in a consistent manner, and maintain such electronic information systems and technology assets according to the covered entity's or business associate's established secure baselines.", "textKind": "verbatim", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "fedramp_config_management", "relation": "partial", "rationale": "Overlap: the FEDRAMP mapping fedramp_config_management (CM Configuration Management) evidences audit events and the absence of UNSIGNED_POLICY_LOADED or GOVERNANCE_BYPASS_SUCCEEDED audits, which bears on part of this clause. Not evidenced: Signed-policy checks cover AMC's own config, not a secure baseline for the agent host."}]},
  {"controlId": "NPRM-164.312(d)", "framework": "HIPAA", "category": "§164.312 Technical Safeguards", "title": "Audit trail and system log controls with real-time monitoring and alerting", "text": "(1) General. Deploy technology assets and/or technical controls that record and identify activity in the covered entity's or business associate's relevant electronic information systems. (2) Implementation specifications —(i) Monitor and identify. The covered entity or business associate must deploy technology assets and/or technical controls that monitor in real-time all activity in its relevant electronic information systems, identify indications of unauthorized persons or unauthorized activity as determined by the covered entity's or business associate's risk analysis under § 164.308(a)(2), and alert workforce members of such indications", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_technical_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_technical_safeguards (§164.312 Technical Safeguards) addresses part of the clause with audit/tool_action events, the exfiltration pack and the pii-detection-leakage pack. Not evidenced: AMC's evidence ledger is recorded after the fact; nothing evidences real-time alerting to a workforce member."}, {"mappingId": "iso_logging_monitoring", "relation": "partial", "rationale": "Overlap: the ISO_27001 mapping iso_logging_monitoring (Logging & Monitoring) evidences audit/metric/llm_request/llm_response events, which bears on part of this clause. Not evidenced: AMC's evidence ledger is recorded after the fact; nothing evidences real-time alerting to a workforce member."}]},
  {"controlId": "NPRM-164.312(e)", "framework": "HIPAA", "category": "§164.312 Technical Safeguards", "title": "Integrity at rest and in transit, tested every 12 months", "text": "Deploy technical controls to protect electronic protected health information from improper alteration or destruction, both at rest and in transit; and review and test the effectiveness of such technical controls at least once every 12 months", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_technical_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_technical_safeguards (§164.312 Technical Safeguards) addresses part of the clause with audit/tool_action events, the exfiltration pack and the pii-detection-leakage pack. Not evidenced: No check that an agent's write tools cannot silently alter ePHI records."}]},
  {"controlId": "NPRM-164.312(f)", "framework": "HIPAA", "category": "§164.312 Technical Safeguards", "title": "Authentication of persons and technology assets; MFA", "text": "(1) General. Deploy technical controls to verify that a person or technology asset seeking access to electronic protected health information and/or the covered entity's or business associate's relevant electronic information systems is the one claimed. [..] (ii) Multi-factor authentication. (A) Deploy multi-factor authentication to all technology assets in the covered entity's or business associate's relevant electronic information systems to verify that a person seeking access to the relevant electronic information system(s) is the user that the person claims to be. (B) Deploy multi-factor authentication for any action that would change a user's privileges", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_technical_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_technical_safeguards (§164.312 Technical Safeguards) addresses part of the clause with audit/tool_action events, the exfiltration pack and the pii-detection-leakage pack. Not evidenced: agentIdentitySpoofing evidences resistance to identity spoofing; AMC does not evidence MFA on the human who authorises an agent or a privilege change."}, {"mappingId": "fedramp_identification_authentication", "relation": "partial", "rationale": "Overlap: the FEDRAMP mapping fedramp_identification_authentication (IA Identification and Authentication) evidences audit events and the agentIdentitySpoofing pack, which bears on part of this clause. Not evidenced: agentIdentitySpoofing evidences resistance to identity spoofing; AMC does not evidence MFA on the human who authorises an agent or a privilege change."}]},
  {"controlId": "NPRM-164.312(g)", "framework": "HIPAA", "category": "§164.312 Technical Safeguards", "title": "Transmission security", "text": "Deploy technical controls to guard against unauthorized access to electronic protected health information that is being transmitted over an electronic communications network; and review and test the effectiveness of such technical controls at least once every 12 months", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_technical_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_technical_safeguards (§164.312 Technical Safeguards) addresses part of the clause with audit/tool_action events, the exfiltration pack and the pii-detection-leakage pack. Not evidenced: No check of TLS on agent-to-model and agent-to-tool channels."}]},
  {"controlId": "NPRM-164.312(h)", "framework": "HIPAA", "category": null, "title": "Vulnerability scanning every 6 months and penetration testing every 12 months", "text": "(1) General. Deploy technical controls in accordance with the covered entity's or business associate's patch management policies and procedures required by § 164.308(a)(4)(ii)(A) to identify and address technical vulnerabilities in the covered entity's or business associate's relevant electronic information systems. [..] at least once every six months, whichever is more frequent. [..] (B) Penetration testing must be performed at least once every 12 months or in accordance with the covered entity's or business associate's risk analysis required by § 164.308(a)(2), whichever is more frequent.", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "pci_dss_vulnerability_mgmt", "relation": "partial", "rationale": "Overlap: the PCI_DSS mapping pci_dss_vulnerability_mgmt (Req 11 Test Security Regularly) evidences the sandboxBoundary pack, which bears on part of this clause. Not evidenced: AMC adversarial packs exercise the agent; they are not a penetration test of the relevant electronic information systems by a qualified person, and no cadence is checked."}, {"mappingId": "fedramp_risk_assessment", "relation": "partial", "rationale": "Overlap: the FEDRAMP mapping fedramp_risk_assessment (RA Risk Assessment) evidences test/audit events and the injection pack, which bears on part of this clause. Not evidenced: AMC adversarial packs exercise the agent; they are not a penetration test of the relevant electronic information systems by a qualified person, and no cadence is checked."}]},
  {"controlId": "NPRM-164.312(i)", "framework": "HIPAA", "category": null, "title": "Data backups no more than 48 hours old", "text": "(1) General. Deploy technical controls to create and maintain exact retrievable copies of electronic protected health information. [..] no more than 48 hours older than the electronic protected health information maintained in the covered entity or business associate's relevant electronic information systems.", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": []},
  {"controlId": "NPRM-164.312(j)", "framework": "HIPAA", "category": null, "title": "Information systems backup and recovery, tested every six months", "text": "Deploy technical controls to create and maintain backups of relevant electronic information systems; and review and test the effectiveness of such technical controls at least once every six months", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": []},
  {"controlId": "NPRM-164.314(a)", "framework": "HIPAA", "category": "§164.314 Organizational Requirements", "title": "BA contract terms: report security incidents and contingency-plan activation within 24 hours", "text": "(C) Report to the covered entity any security incident of which it becomes aware, including breaches of unsecured electronic protected health information as required by § 164.410. (D) Report to the covered entity activation of its contingency plan under § 164.308(a)(13) without unreasonable delay, and in no case later than 24 hours after activation of the contingency plan.", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_organizational_requirements", "relation": "partial", "rationale": "This family's mapping hipaa_organizational_requirements (§164.314 Organizational Requirements) addresses part of the clause with audit events and the delegationTrustChain pack. Not evidenced: No AMC evidence of BA-to-CE notification timing."}, {"mappingId": "hipaa_breach_notification", "relation": "partial", "rationale": "This family's mapping hipaa_breach_notification (Breach Notification Rule §164.400-414) addresses part of the clause with audit/metric events and the absence of SECRET_EXFILTRATION_SUCCEEDED audits. Not evidenced: No AMC evidence of BA-to-CE notification timing."}]},
  {"controlId": "NPRM-164.316", "framework": "HIPAA", "category": "§164.316 Policies and Documentation", "title": "Document each action, retain 6 years, review every 12 months", "text": "(2) Document each action, activity, or assessment required by this subpart. (b) Implementation specifications —(1) Time limit. Retain the documentation required by paragraph (a) of this section for 6 years from the date of its creation or the date when it last was in effect, whichever is later. [..] (3) Updates. Review and update documentation at least once every 12 months", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_policies_documentation", "relation": "partial", "rationale": "This family's mapping hipaa_policies_documentation (§164.316 Policies and Documentation) addresses part of the clause with audit/test events and the absence of GOVERNANCE_BYPASS_SUCCEEDED or EXECUTE_WITHOUT_TICKET_ATTEMPTED audits. Not evidenced: AMC ledger retention is not configured or evidenced against a 6-year period."}]},
  {"controlId": "NPRM-preamble-AI", "framework": "HIPAA", "category": null, "title": "AI tools in the asset inventory and risk analysis", "text": "ePHI, including ePHI in AI training data, prediction models, and algorithm data that is maintained by a regulated entity for covered functions is protected by the HIPAA Rules and all applicable standards and specifications. [..] we expect that a regulated entity interested in using AI would include the use of such tools in its risk analyses and associated risk management activities. The regulated entity's risk analysis must include consideration of, among other things, the type and amount of ePHI accessed by the AI tool, to whom the data is disclosed, and to whom the output is provided. [..] the Department would expect that AI software used to create, receive, maintain, or transmit ePHI or that interacts with ePHI, including where ePHI is used to train the AI software, would be listed as part of its technology asset inventory", "textKind": "verbatim-excerpt", "status": "proposed", "sourceUrl": "https://www.federalregister.gov/documents/full_text/html/2025/01/06/2024-30983.html", "retrievedAt": "2026-10-04", "verified": true, "mappings": [{"mappingId": "hipaa_administrative_safeguards", "relation": "partial", "rationale": "This family's mapping hipaa_administrative_safeguards (§164.308 Administrative Safeguards) addresses part of the clause with audit/llm_request/tool_action events, the governance_bypass pack and the absence of GOVERNANCE_BYPASS_SUCCEEDED or EXECUTE_WITHOUT_TICKET_ATTEMPTED audits. Not evidenced: AMC does not record, per agent, the type and amount of ePHI accessed, the recipients of disclosed data, or the recipients of output, as a risk-analysis input."}, {"mappingId": "hipaa_privacy_rule", "relation": "partial", "rationale": "This family's mapping hipaa_privacy_rule (§164.502-514 Privacy Rule Uses and Disclosures) addresses part of the clause with the pii-detection-leakage pack and the context-leakage pack. Not evidenced: AMC does not record, per agent, the type and amount of ePHI accessed, the recipients of disclosed data, or the recipients of output, as a risk-analysis input."}]},
];
